from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test_order")
async def test_order(form_val: str = Form(...), file_val: UploadFile = File(...)):
    return {"form_val": form_val, "file_val": file_val.filename}

@app.post("/test_multiple_files")
async def test_multiple_files(
    form_val: str = Form(...), 
    file1: UploadFile = File(...), 
    file2: UploadFile = File(...)
):
    return {"form_val": form_val, "file1": file1.filename, "file2": file2.filename}

client = TestClient(app)

def test_form_before_file():
    files = {"file_val": ("filename", b"contents")}
    data = {"form_val": "foo"}
    response = client.post("/test_order", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_val": "foo", "file_val": "filename"}

def test_multiple_files_with_form():
    files = {
        "file1": ("file1.txt", b"content1"),
        "file2": ("file2.txt", b"content2"),
    }
    data = {"form_val": "bar"}
    response = client.post("/test_multiple_files", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_val": "bar", "file1": "file1.txt", "file2": "file2.txt"}

